 source=receipt.get('target',receipt.get('source_blend',receipt.get('source')))
 card={'name':name,'previous_score':previous,'source_score':round(normalized,2),'source_score_method':'Five source-art criteria normalized by their 90% total weight; not a complete acceptance score.','criterion_scores':dict(zip(CRITERIA,scores+[None])),'weights':dict(zip(CRITERIA,WEIGHTS+[.1])),'known_weighted_subtotal':round(subtotal,3),'full_score_interval_pending_owner_colour':[round(subtotal,3),round(subtotal+1,3)],'target_met':False,'owner_colour':'N/V: final native two-colour test pending','deductions':deductions,'improvements':improved,'evidence_links':[str(before),str(after),str(agame),str(official),str(sheetpath)],'source':source,'revision':revision,'regional_reference':region}
 cards[f]=card
 card['criterion_evidence']={CRITERIA[0]:{'image':str(after),'observation':improved[0]+' '+deductions[0]},CRITERIA[1]:{'image':str(agame),'observation':'Main silhouette remains identifiable at gameplay distance; unresolved hierarchy is described in the first deduction.'},CRITERIA[2]:{'image':str(after),'regional_source':region[1],'observation':region[2]},CRITERIA[3]:{'image':str(after),'observation':deductions[1]+' Source material projection does not prove native shading.'},CRITERIA[4]:{'image':str(agame),'observation':deductions[2]},CRITERIA[5]:{'observation':'No native two-colour capture. Stock flag integration alone is not functional ownership proof.'}}
 table=''.join(f'<tr><td>{html.escape(c)}</td><td>{s if s is not None else "N/V — native test pending"}</td><td>{int(w*100)}%</td><td>{html.escape(card["criterion_evidence"][c]["observation"])}</td></tr>'for c,s,w in zip(CRITERIA,scores+[None],WEIGHTS+[.1]))
 sections.append(f'<section id="{f}"><h2>{html.escape(name)} · {previous:g} → {normalized:.1f}/10 provisional source art</h2><p>The current number uses the five inspectable source-art criteria only. Full rubric interval: {subtotal:.2f}–{subtotal+1:.2f}, with owner colour unverified. Target not met.</p><a href="{f}-comparison.png"><img src="{f}-comparison.png" alt="{html.escape(name)} comparison sheet"></a><table><tr><th>Criterion</th><th>Score</th><th>Weight</th><th>Visible evidence and deduction (sheet above)</th></tr>{table}</table><h3>Improvements</h3><ul>'+''.join('<li>'+html.escape(x)+'</li>'for x in improved)+'</ul><h3>Three remaining weaknesses</h3><ol>'+''.join('<li>'+html.escape(x)+'</li>'for x in deductions)+f'</ol><p>Regional reference: <a href="{html.escape(region[1])}">{html.escape(region[0])}</a>. {html.escape(region[2])}</p><p>Model-mesh upper bound including all body states, retained native props/scaffolds and flag: <b>{perf["compound_model_mesh_upper"]:,}</b>. Source healthy vertices: {verts:,}. Body textures: '+', '.join(f'{t["name"]} {t["dimensions"][0]}×{t["dimensions"][1]}'for t in textures)+'. Native memory/draw calls/LOD switching remain unmeasured.</p><p>Reference lower bound: '+comparator+' '+format(lower,',')+' principal healthy triangles. '+html.escape(perf['comparison']['qualification'])+'</p><p>'+link(Path(source),'Editable Blender source')+' · '+link(BASE/'art'/f/revision/'receipt.json','Source receipt')+' · '+link(agame,'Full gameplay-distance preview')+'</p></section>')
